"""HTML shell for the curriculum board (loop #122).

Lifted VERBATIM from the hand-maintained page Joe already has, so the first
generated render is byte-identical in design to what he was looking at. The card
list between HEAD and TAIL is the only part the exporter generates; everything
else — palette, filters, the browsing script — is his page, unchanged.

Regenerate this file only by re-lifting from a page Joe has approved.
"""

HEAD = '<!DOCTYPE html>\n<html lang="en">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1.0">\n<title>Joe\'s Curriculum — recommended by Doc</title>\n<style>\n  :root{\n    --bg:#0d1b2a; --card:#13263a; --card2:#0f2032; --line:#1e3a54;\n    --teal:#3fd0c9; --amber:#f0a35e; --text:#dce8f2; --dim:#8aa5bb; --done:#5f7d95;\n  }\n  *{box-sizing:border-box; margin:0; padding:0;}\n  body{background:var(--bg); color:var(--text); font-family:-apple-system,BlinkMacSystemFont,\'Segoe UI\',Roboto,sans-serif; padding:24px 16px 60px; max-width:760px; margin:0 auto;}\n  header{margin-bottom:6px;}\n  h1{font-size:1.35rem; font-weight:600; letter-spacing:.2px;}\n  h1 .dr{color:var(--teal);}\n  .sub{color:var(--dim); font-size:.85rem; margin-top:4px; line-height:1.45;}\n  .sub b{color:var(--text); font-weight:600;}\n  .filters{display:flex; flex-wrap:wrap; gap:8px; margin:18px 0 14px;}\n  .filters button{\n    background:var(--card2); color:var(--dim); border:1px solid var(--line);\n    border-radius:999px; padding:6px 14px; font-size:.8rem; cursor:pointer; transition:all .15s;\n  }\n  .filters button.active{background:var(--teal); color:#062225; border-color:var(--teal); font-weight:600;}\n  .count{color:var(--dim); font-size:.75rem; margin-bottom:10px;}\n  .card{\n    background:var(--card); border:1px solid var(--line); border-left:3px solid var(--teal);\n    border-radius:10px; padding:16px 16px 14px; margin-bottom:12px;\n  }\n  .card.status-done{border-left-color:var(--done); opacity:.75;}\n  .card.priority-now{border-left-color:var(--amber);}\n  .top{display:flex; justify-content:space-between; align-items:baseline; gap:10px; flex-wrap:wrap;}\n  .title{font-size:1.02rem; font-weight:600;}\n  .author{color:var(--dim); font-weight:400;}\n  .tags{display:flex; gap:6px; flex-wrap:wrap; margin-top:8px;}\n  .tag{font-size:.68rem; letter-spacing:.4px; text-transform:uppercase; padding:3px 8px; border-radius:4px; background:var(--card2); color:var(--dim); border:1px solid var(--line);}\n  .tag.type{color:var(--teal); border-color:rgba(63,208,201,.35);}\n  .tag.now{color:var(--amber); border-color:rgba(240,163,94,.4);}\n  .why{margin-top:10px; font-size:.88rem; line-height:1.55; color:var(--text);}\n  .why b{color:var(--teal); font-weight:600;}\n  .meta{margin-top:10px; font-size:.75rem; color:var(--dim);}\n  .empty{color:var(--dim); text-align:center; padding:40px 0; display:none; font-size:.9rem;}\n  footer{margin-top:26px; color:var(--dim); font-size:.75rem; line-height:1.6; border-top:1px solid var(--line); padding-top:14px;}\n</style>\n</head>\n<body>\n<header>\n  <h1>Joe\'s Curriculum <span class="dr">· recommended by Doc</span></h1>\n  <p class="sub">Every recommendation ties to an <b>observed pattern</b>, never a listicle. Nothing here is homework — untouched items just wait. To change a status or add a note, tell any session (<i>"mark Marquet done"</i>) and this board regenerates. Rendered 2026-08-01.</p>\n</header>\n\n<div class="filters" id="filters">\n  <button data-f="all" class="active">All</button>\n  <button data-f="priority-now">Start here</button>\n  <button data-f="type-book">Books</button>\n  <button data-f="type-media">Talks &amp; media</button>\n  <button data-f="status-new">Unread</button>\n  <button data-f="status-done">Finished</button>\n</div>\n<div class="count" id="count"></div>\n\n<div id="list">'

TAIL = '<p class="empty" id="empty">Nothing in this filter yet. Doc adds items only when a pattern earns one.</p>\n\n<footer>\n  This board is a <b>render</b> — one writer, like everything else. Doc adds recommendations when the ledgers produce a reason; you change statuses by saying so in any session. Filters are for browsing only.<br>\n  Source of truth: media-recommendation records in the record layer · Design: Doc palette v1 (navy / teal / amber-reserved).\n</footer>\n\n<script>\n  const buttons = document.querySelectorAll(\'#filters button\');\n  const cards = Array.from(document.querySelectorAll(\'#list .card\'));\n  const empty = document.getElementById(\'empty\');\n  const count = document.getElementById(\'count\');\n  function apply(f){\n    let shown = 0;\n    cards.forEach(c => {\n      const show = (f === \'all\') || c.classList.contains(f);\n      c.style.display = show ? \'\' : \'none\';\n      if (show) shown++;\n    });\n    empty.style.display = shown ? \'none\' : \'block\';\n    count.textContent = shown + \' of \' + cards.length + \' items\';\n  }\n  buttons.forEach(b => b.addEventListener(\'click\', () => {\n    buttons.forEach(x => x.classList.remove(\'active\'));\n    b.classList.add(\'active\');\n    apply(b.dataset.f);\n  }));\n  apply(\'all\');\n</script>\n</body>\n</html>\n'
